  function genTales(level) {
    const T = U.pick(TALES);
    const h = U.pick(HERO_OF);
    const qt = U.pick(TALE_QUOTES);
    const K = U.pick(TALES.filter(x => x.kind));
    if (level === 1) return run([
      () => big('Из какой сказки этот герой: <b>' + h[0] + '</b>?', h[1], U.pickN(TALES.map(x => x.t).filter(x => x !== h[1]), 2), { hint: 'Вспомни, кто встречается в этой сказке', explain: U.cap(h[0]) + ' — герой сказки ' + q(h[1]) + '.' }),
      () => choice('Чему учит сказка ' + q(T.t) + '?', T.lesson, U.pickN(TALES.filter(x => x !== T).map(x => x.lesson), 2), { hint: 'Подумай, что главное в этой сказке', explain: 'Сказка ' + q(T.t) + ' учит: ' + T.lesson + '.' }),
      () => match('Соедини сказку и её героя', HERO_OF.map(x => [x[1], x[0]]), 3, { explain: 'У каждой сказки свои герои.' }),
      () => choice('Кто сказал эти слова?', qt[1], U.pickN(U.uniq(TALE_QUOTES.map(x => x[1])).filter(x => x !== qt[1]), 2), { visual: P('— ' + qt[0]), hint: 'Это из сказки ' + q(qt[2]), explain: 'Так говорит ' + qt[1] + ' в сказке ' + q(qt[2]) + '.' }),
      () => order('Кто за кем тянул репку?', taleOf('Репка').heroes.slice(0, 4), { hint: 'Дед позвал бабку, бабка — внучку…', explain: 'Дед, бабка, внучка, Жучка, кошка, мышка.' }),
      () => order('Кто за кем пришёл в теремок?', taleOf('Теремок').heroes.slice(0, 3), { explain: 'Мышка-норушка, лягушка-квакушка, зайчик-побегайчик, лисичка, волчок, медведь.' })
    ]);
    if (level === 2) return run([
      () => order('Расставь события сказки ' + q(T.t) + ' по порядку', T.ord.slice(0, 4), { explain: 'В сказке всё идёт по порядку: ' + T.ord[0] + ' → … → ' + T.ord[T.ord.length - 1] + '.' }),
      () => choice('Кто сказал эти слова?', qt[1], U.pickN(U.uniq(TALE_QUOTES.map(x => x[1])).filter(x => x !== qt[1]), 3), { visual: P('— ' + qt[0]), explain: 'Это слова героя по имени «' + qt[1] + '» из сказки ' + q(qt[2]) + '.' }),
      () => choice('Из какой сказки эти слова?', qt[2], U.pickN(TALES.map(x => x.t).filter(x => x !== qt[2]), 3), { visual: P('— ' + qt[0]), explain: 'Это сказка ' + q(qt[2]) + '.' }),
      () => choice('Какая это сказка?', K.kind, KINDS.filter(x => x !== K.kind), { visual: P('Сказка ' + q(K.t)), hint: 'Посмотри, кто главные герои и есть ли волшебство', explain: q(K.t) + ' — сказка ' + K.kind + ': ' + KIND_HINT[K.kind] + '.' }),
      () => multi('Выбери <b>всех</b> героев сказки ' + q(T.t), U.pickN(T.heroes, Math.min(3, T.heroes.length)), U.pickN(TALES.filter(x => x !== T).map(x => U.pick(x.heroes)).filter(x => !T.heroes.includes(x)), 3), { explain: 'В сказке ' + q(T.t) + ' действуют: ' + T.heroes.join(', ') + '.' }),
      () => match('Соедини сказку и её героя', HERO_OF.map(x => [x[1], x[0]]), 4, { explain: 'По герою легко узнать сказку.' }),
      () => choice('Из какой сказки этот герой: <b>' + h[0] + '</b>?', h[1], U.pickN(TALES.map(x => x.t).filter(x => x !== h[1]), 3), { explain: U.cap(h[0]) + ' — из сказки ' + q(h[1]) + '.' })
    ]);
    return run([
      () => order('Расставь события сказки ' + q(T.t) + ' по порядку', T.ord.slice(), { explain: 'Порядок событий: ' + T.ord.map((x, i) => (i + 1) + ') ' + x).join('; ') + '.' }),
      () => sortG('Разложи сказки по видам', KINDS.map(k => g(U.cap(k) + (k === 'волшебная' ? ' 🪄' : k === 'бытовая' ? ' 🏠' : ' 🐾'), KIND_TITLES[k])), 2, { explain: 'О животных — герои звери; волшебная — есть чудеса; бытовая — про людей и смекалку.' }),
      () => { const ti = U.pick(TALE_INPUT); return input(ti[0], ti[1].slice(), { hint: 'Ответ начинается на «' + ti[1][0][0] + '»', explain: ti[2] }); },
      () => match('Соедини сказку и то, чему она учит', TALES.map(x => [q(x.t), x.lesson]), 4, { explain: 'В каждой сказке есть урок.' }),
      () => choice('Кто сказал эти слова?', qt[1], U.pickN(U.uniq(TALE_QUOTES.map(x => x[1])).filter(x => x !== qt[1]), 4), { visual: P('— ' + qt[0]), explain: 'Это ' + qt[1] + ', сказка ' + q(qt[2]) + '.' }),
      () => order('Расставь героев ' + q('Теремка') + ' по порядку появления', taleOf('Теремок').heroes.slice(), { explain: 'Мышка, лягушка, зайчик, лисичка, волчок, медведь — и теремок развалился.' }),
      () => order('Кто за кем тянул репку?', taleOf('Репка').heroes.slice(), { explain: 'Дед — бабка — внучка — Жучка — кошка — мышка.' }),
      () => multi('Выбери <b>все</b> волшебные сказки', U.pickN(KIND_TITLES['волшебная'], 3), U.pickN(KIND_TITLES['о животных'], 2), { explain: 'В волшебной сказке есть чудеса, превращения и волшебные помощники.' }),
      () => choice('Какая это сказка?', K.kind, KINDS.filter(x => x !== K.kind), { visual: P('Сказка ' + q(K.t) + '. Герои: ' + taleOf(K.t).heroes.slice(0, 3).join(', ') + '…'), explain: q(K.t) + ' — сказка ' + K.kind + '.' })
    ]);
  }

