  function genClassics(level) {
    const w = U.pick(CL_WORKS);
    const gp = U.pick(CL_GAPS);
    const cq = U.pick(CL_Q);
    const m = U.pick(CL_MORAL);
    const ls = U.pick(CL_LESSON);
    if (level === 1) return run([
      () => choice('Кто написал ' + q(w[0]) + '?', w[1], CL_AUTHORS.filter(x => x !== w[1]), { hint: 'Пушкин — сказки и стихи, Крылов — басни, Толстой — рассказы', explain: q(w[0]) + ' написал ' + w[1] + '.' }),
      () => gap('Закончи строку', gp[0], [gp[1]], gp[2].slice(0, 1), { hint: 'Прочитай строку вслух — так слышнее', explain: gp[0].replace('_', gp[1]) + '.' }),
      () => { const h = U.pick(CL_HEROES); return choice('Из какого произведения этот герой: <b>' + h[1] + '</b>?', q(h[0]), U.pickN(CL_HEROES.filter(x => x[0] !== h[0]).map(x => q(x[0])), 2), { explain: U.cap(h[1]) + ' — из произведения ' + q(h[0]) + '.' }); },
      () => choice(cq[0], cq[1], U.pickN(cq[2], 2), { hint: 'Вспомни, чем всё закончилось', explain: U.cap(cq[1]) + '.' }),
      () => match('Соедини произведение и его героя', CL_HEROES.map(x => [q(x[0]), x[1]]), 3, { explain: 'По герою можно узнать книгу.' }),
      () => order('Что старуха просила у рыбки? Расставь по порядку', WISHES.slice(0, 3), { hint: 'Сначала самое простое — корыто', explain: 'Корыто → изба → дворянка → царица → владычица морская.' })
    ]);
    if (level === 2) return run([
      () => gap('Закончи строку', gp[0], [gp[1]], gp[2], { explain: gp[0].replace('_', gp[1]) + '.' }),
      () => choice('Кто написал ' + q(w[0]) + '?', w[1], CL_AUTHORS.filter(x => x !== w[1]), { explain: q(w[0]) + ' — это ' + w[1] + '.' }),
      () => choice('Чему учит басня ' + q(m[0]) + '?', m[1], U.pickN(CL_MORAL.filter(x => x !== m).map(x => x[1]), 3), { explain: 'Мораль басни: ' + m[1] + '.' }),
      () => choice('Чему учит рассказ Л. Н. Толстого ' + q(ls[0]) + '?', ls[1], U.pickN(CL_LESSON.filter(x => x !== ls).map(x => x[1]), 3), { explain: q(ls[0]) + ' учит: ' + ls[1] + '.' }),
      () => order('Что старуха просила у рыбки? Расставь по порядку', WISHES.slice(), { explain: 'Корыто, изба, дворянка, царица, владычица морская — и снова разбитое корыто.' }),
      () => choice(cq[0], cq[1], cq[2], { explain: U.cap(cq[1]) + '.' }),
      () => match('Соедини произведение и его героя', CL_HEROES.map(x => [q(x[0]), x[1]]), 4, { explain: 'Герои помогают вспомнить произведение.' }),
      () => { const a = U.pick(CL_AUTHORS); const right = U.pickN(clWorksOf(a), 2); const wr = U.pickN(CL_WORKS.filter(x => x[1] !== a).map(x => q(x[0])), 3); return multi('Выбери <b>все</b> произведения, которые написал ' + a, right, wr, { explain: a + ' написал: ' + clWorksOf(a).join(', ') + '.' }); }
    ]);
    return run([
      () => { const o = U.pick(CL_ORD); return order('Расставь события ' + q(o[0]) + ' по порядку', o[1].slice(), { explain: 'Порядок: ' + o[1].map((x, i) => (i + 1) + ') ' + x).join('; ') + '.' }); },
      () => sortG('Разложи произведения по авторам', CL_AUTHORS.map(a => g(a, clWorksOf(a))), 2, { explain: 'Пушкин — сказки и стихи, Крылов — басни, Толстой — рассказы для детей.' }),
      () => input('Закончи строку одним словом: <b>' + gp[0].replace('_', '…') + '</b>', [gp[1]], { hint: 'Первая буква: ' + gp[1][0], explain: gp[0].replace('_', gp[1]) + '.' }),
      () => match('Соедини произведение и его героя', CL_HEROES.map(x => [q(x[0]), x[1]]), 5, { explain: 'Каждый герой живёт в своём произведении.' }),
      () => match('Соедини басню и её мораль', CL_MORAL.map(x => [q(x[0]), x[1]]), 4, { explain: 'Мораль — главный урок басни, он обычно в конце.' }),
      () => order('Что старуха просила у рыбки? Расставь по порядку', WISHES.slice(), { explain: 'Чем больше старуха получала, тем больше хотела — и осталась ни с чем.' }),
      () => choice(cq[0], cq[1], cq[2].concat(U.pick(CL_Q.filter(x => x !== cq))[2].slice(0, 1)), { explain: U.cap(cq[1]) + '.' }),
      () => { const a = U.pick(CL_AUTHORS); const right = U.pickN(clWorksOf(a), 3); const wr = U.pickN(CL_WORKS.filter(x => x[1] !== a).map(x => q(x[0])), 3); return multi('Выбери <b>все</b> произведения, которые написал ' + a, right, wr, { explain: a + ' — автор этих произведений.' }); },
      () => match('Соедини рассказ Толстого и его главную мысль', CL_LESSON.map(x => [q(x[0]), x[1]]), 4, { explain: 'Рассказы Толстого коротки, но в каждом есть урок.' })
    ]);
  }

