  function genWriters(level) {
    const w = U.pick(WR_WORKS);
    const h = U.pick(WR_HEROES);
    const pl = U.pick(WR_PLOT);
    if (level === 1) return run([
      () => choice('Кто написал ' + q(w[0]) + '?', w[1], U.pickN(WR_AUTHORS.filter(x => x !== w[1]), 2), { hint: 'Чуковский — сказки в стихах, Носов — весёлые рассказы', explain: q(w[0]) + ' написал ' + w[1] + '.' }),
      () => choice('Кто это: <i>' + h[0] + '</i>?', q(h[1]), U.pickN(WR_HEROES.filter(x => x[1] !== h[1]).map(x => q(x[1])), 2), { hint: 'Вспомни, в какой книге такой герой', explain: U.cap(h[0]) + ' — из произведения ' + q(h[1]) + '.' }),
      () => choice(pl[0], pl[1], U.pickN(pl[2], 2), { hint: 'Вспомни, что там произошло', explain: U.cap(pl[1]) + '.' }),
      () => match('Соедини героя и произведение', WR_HEROES.map(x => [x[0], q(x[1])]), 3, { explain: 'У каждого героя своя книга.' }),
      () => { const a = U.pick(WR_AUTHORS); return choice('Кто из этих писателей написал ' + U.pick(wrWorksOf(a)) + '?', a, U.pickN(WR_AUTHORS.filter(x => x !== a), 2), { explain: 'Это написал ' + a + '.' }); }
    ]);
    if (level === 2) return run([
      () => choice('Кто написал ' + q(w[0]) + '?', w[1], U.pickN(WR_AUTHORS.filter(x => x !== w[1]), 3), { explain: q(w[0]) + ' — это ' + w[1] + '.' }),
      () => choice(pl[0], pl[1], pl[2], { explain: U.cap(pl[1]) + '.' }),
      () => choice('Из какого произведения этот герой: <i>' + h[0] + '</i>?', q(h[1]), U.pickN(WR_HEROES.filter(x => x[1] !== h[1]).map(x => q(x[1])), 3), { explain: 'Это ' + q(h[1]) + ', автор — ' + wrOf(h[1]) + '.' }),
      () => match('Соедини героя и произведение', WR_HEROES.map(x => [x[0], q(x[1])]), 4, { explain: 'Героя легко узнать по тому, что с ним случилось.' }),
      () => { const a = U.pick(WR_AUTHORS); const right = U.pickN(wrWorksOf(a), 2); const wr = U.pickN(WR_WORKS.filter(x => x[1] !== a).map(x => q(x[0])), 3); return multi('Выбери <b>все</b> произведения, которые написал ' + a, right, wr, { explain: a + ' написал ' + wrWorksOf(a).slice(0, 4).join(', ') + ' и другие.' }); },
      () => { const wi = U.pick(WR_INPUT); return input(wi[0], wi[1].slice(), { hint: 'Первая буква: ' + wi[1][0][0], explain: wi[2] }); }
    ]);
    return run([
      () => sortG('Разложи произведения по авторам', U.pickN(WR_AUTHORS, 3).map(a => g(a, wrWorksOf(a))), 2, { explain: 'Чуковский — сказки в стихах, Маршак — стихи и сказки, Михалков — про дядю Стёпу, Барто — про детей и игрушки, Носов — весёлые рассказы.' }),
      () => { const wi = U.pick(WR_INPUT); return input(wi[0], wi[1].slice(), { explain: wi[2] }); },
      () => match('Соедини героя и произведение', WR_HEROES.map(x => [x[0], q(x[1])]), 5, { explain: 'Проверь себя: вспомни, что случилось с каждым героем.' }),
      () => choice(pl[0], pl[1], pl[2].concat(U.pick(WR_PLOT.filter(x => x !== pl))[2].slice(0, 1)), { explain: U.cap(pl[1]) + '.' }),
      () => { const a = U.pick(WR_AUTHORS); const right = U.pickN(wrWorksOf(a), 3); const wr = U.pickN(WR_WORKS.filter(x => x[1] !== a).map(x => q(x[0])), 3); return multi('Выбери <b>все</b> произведения, которые написал ' + a, right, wr, { explain: 'Это произведения, которые написал ' + a + '.' }); },
      () => { const a = U.pick(WR_AUTHORS); return choice('Кто написал ' + U.pickN(wrWorksOf(a), 2).join(' и ') + '?', a, U.pickN(WR_AUTHORS.filter(x => x !== a), 3), { explain: 'Оба произведения написал ' + a + '.' }); },
      () => match('Соедини произведение и автора', U.pickN(WR_AUTHORS, 4).map(a => [q(U.pick(wrWorksOf(a)).replace(/[«»]/g, '')), a]), 4, { explain: 'У каждого произведения свой автор.' })
    ]);
  }

