  const AN_GOOD = ['насыпать птицам корм в кормушку', 'отпустить пойманного жука на волю', 'обойти гнездо стороной', 'налить воды бездомному котёнку', 'кормить свою собаку вовремя', 'помочь птенцу вернуться в гнездо'];
