  const anOf = a => AN.filter(x => x.a === a).map(x => q(x.t));

  function genAnimals(level) {
    const r = U.pick(AN);
    const aq = U.pick(AN_Q);
    if (level === 1) return run([
      () => choice('О ком этот рассказ: ' + q(r.t) + '?', r.about, U.pickN(AN.filter(x => x !== r).map(x => x.about), 2), { hint: 'Вспомни, кто главный герой', explain: q(r.t) + ' — это рассказ про то, как ' + r.about + '.' }),
      () => choice(aq[0], aq[1], U.pickN(aq[2], 2), { hint: 'Подумай, что было в рассказе', explain: U.cap(aq[1]) + '.' }),
      () => choice('Кто написал рассказ ' + q(r.t) + '?', r.a, U.pickN(AN_AUTHORS.filter(x => x !== r.a), 2), { explain: q(r.t) + ' написал ' + r.a + '.' }),
      () => match('Соедини рассказ и его героя', AN.map(x => [q(x.t), x.who]), 3, { explain: 'В каждом рассказе свой герой-зверёк.' }),
      () => sortG('Как надо и как нельзя поступать с животными?', [g('Так надо 💚', AN_GOOD), g('Так нельзя ❌', AN_BAD)], 2, { explain: 'Животных надо беречь: не трогать гнёзда, не ловить, не обижать.' })
    ]);
    if (level === 2) return run([
      () => choice(aq[0], aq[1], aq[2], { explain: U.cap(aq[1]) + '.' }),
      () => order('Расставь события рассказа ' + q(r.t) + ' по порядку', r.ord.slice(0, 4), { explain: 'Сначала ' + r.ord[0] + ', а в конце ' + r.ord[r.ord.length - 1] + '.' }),
      () => choice('Кто написал рассказ ' + q(r.t) + '?', r.a, U.pickN(AN_AUTHORS.filter(x => x !== r.a), 3), { explain: 'Автор — ' + r.a + '.' }),
      () => choice('Какая главная мысль рассказа ' + q(r.t) + '?', r.idea, U.pickN(AN.filter(x => x !== r).map(x => x.idea), 3), { explain: q(r.t) + ' учит: ' + r.idea + '.' }),
      () => match('Соедини рассказ и его героя', AN.map(x => [q(x.t), x.who]), 4, { explain: 'Героя легко вспомнить по названию.' }),
      () => sortG('Как надо и как нельзя поступать с животными?', [g('Так надо 💚', AN_GOOD), g('Так нельзя ❌', AN_BAD)], 3, { explain: 'Природа беззащитна перед человеком, поэтому её надо беречь.' })
    ]);
    return run([
      () => order('Расставь события рассказа ' + q(r.t) + ' по порядку', r.ord.slice(), { explain: 'Порядок: ' + r.ord.map((x, i) => (i + 1) + ') ' + x).join('; ') + '.' }),
      () => match('Соедини рассказ и его главную мысль', AN.map(x => [q(x.t), x.idea]), 4, { explain: 'В рассказе о животных всегда есть мысль о бережном отношении к природе.' }),
      () => choice(aq[0], aq[1], aq[2].concat(U.pick(AN_Q.filter(x => x !== aq))[2].slice(0, 1)), { explain: U.cap(aq[1]) + '.' }),
      () => input('Кто написал рассказ ' + q(r.t) + '? Напиши фамилию', [r.a.split(' ').pop()], { hint: 'Первая буква: ' + r.a.split(' ').pop()[0], explain: q(r.t) + ' написал ' + r.a + '.' }),
      () => order('Что за чем случилось в рассказе Бианки ' + q('Сова') + '?', AN.find(x => x.t === 'Сова').ord.slice(), { explain: 'Сова — мыши — шмели — клевер — молоко: в природе всё связано.' }),
      () => multi('Выбери <b>всё</b>, что делать с животными нельзя', U.pickN(AN_BAD, 3), U.pickN(AN_GOOD, 2), { explain: 'Нельзя разорять гнёзда и муравейники, ловить и дразнить животных.' }),
      () => match('Соедини автора и его рассказ', AN_AUTHORS.map(a => [a, U.pick(anOf(a))]), 4, { explain: 'Бианки, Пришвин, Чарушин, Житков и Паустовский писали о природе и животных.' })
    ]);
  }

