  function genFriends(level) {
    const r = U.pick(FR);
    const fq = U.pick(FR_Q);
    if (level === 1) return run([
      () => choice(fq[0], fq[1], U.pickN(fq[2], 2), { hint: 'Подумай, как поступил бы хороший друг', explain: U.cap(fq[1]) + '.' }),
      () => choice('Кто главный герой рассказа ' + q(r.t) + '?', r.who, U.pickN(FR.filter(x => x !== r).map(x => x.who), 2), { explain: 'В рассказе ' + q(r.t) + ' главные герои — ' + r.who + '.' }),
      () => sortG('Разложи поступки: хорошо или плохо?', [g('Хорошо 💚', FR_GOOD), g('Плохо ❌', FR_BAD)], 2, { hint: 'Спроси себя: приятно ли так поступать с тобой?', explain: 'Хорошо — помогать и делиться, плохо — обижать и обманывать.' }),
      () => match('Соедини рассказ и его героя', FR.map(x => [q(x.t), x.who]), 3, { explain: 'Героя легко вспомнить по названию рассказа.' }),
      () => choice('Чему учит рассказ ' + q(r.t) + '?', r.idea, U.pickN(FR.filter(x => x !== r).map(x => x.idea), 2), { explain: q(r.t) + ' учит: ' + r.idea + '.' })
    ]);
    if (level === 2) return run([
      () => choice(fq[0], fq[1], fq[2], { explain: U.cap(fq[1]) + '.' }),
      () => choice('Какая главная мысль рассказа ' + q(r.t) + '?', r.idea, U.pickN(FR.filter(x => x !== r).map(x => x.idea), 3), { explain: 'Главная мысль: ' + r.idea + '.' }),
      () => order('Расставь события рассказа ' + q(r.t) + ' по порядку', r.ord.slice(0, 4), { explain: 'Сначала ' + r.ord[0] + ', потом всё остальное.' }),
      () => choice('Кто написал рассказ ' + q(r.t) + '?', r.a, U.pickN(FR_AUTHORS.filter(x => x !== r.a), 3), { explain: q(r.t) + ' написал ' + r.a + '.' }),
      () => sortG('Разложи поступки: хорошо или плохо?', [g('Хорошо 💚', FR_GOOD), g('Плохо ❌', FR_BAD)], 3, { explain: 'По поступкам видно, какой человек друг.' }),
      () => match('Соедини рассказ и его героя', FR.map(x => [q(x.t), x.who]), 4, { explain: 'У каждого рассказа свои герои.' })
    ]);
    return run([
      () => order('Расставь события рассказа ' + q(r.t) + ' по порядку', r.ord.slice(), { explain: 'Порядок: ' + r.ord.map((x, i) => (i + 1) + ') ' + x).join('; ') + '.' }),
      () => match('Соедини рассказ и его главную мысль', FR.map(x => [q(x.t), x.idea]), 4, { explain: 'В рассказах о друзьях главное — поступок героя.' }),
      () => input('Какое волшебное слово помогло Павлику в рассказе Осеевой?', ['пожалуйста'], { explain: 'Волшебное слово — «пожалуйста», сказанное тихо и вежливо.' }),
      () => multi('Выбери <b>все</b> поступки настоящего друга', U.pickN(FR_GOOD, 3), U.pickN(FR_BAD, 2), { explain: 'Настоящий друг делится, помогает и поддерживает.' }),
      () => choice(fq[0], fq[1], fq[2].concat(U.pick(FR_Q.filter(x => x !== fq))[2].slice(0, 1)), { explain: U.cap(fq[1]) + '.' }),
      () => match('Соедини автора и его рассказ', FR_AUTHORS.map(a => [a, q(U.pick(FR.filter(x => x.a === a)).t)]), 4, { explain: 'Осеева, Ермолаев, Булгаков, Драгунский, Пантелеев и Пермяк писали о дружбе и поступках.' }),
      () => sortG('Разложи поступки: хорошо или плохо?', [g('Хорошо 💚', FR_GOOD), g('Плохо ❌', FR_BAD)], 4, { explain: 'Подумай о каждом поступке: как бы ты себя чувствовала на месте другого?' }),
      () => choice('Какая главная мысль рассказа ' + q(r.t) + '?', r.idea, U.pickN(FR.filter(x => x !== r).map(x => x.idea), 4), { explain: q(r.t) + ': ' + r.idea + '.' })
    ]);
  }

