  function genComp(level) {
    const t = U.pick(TXT);
    const vis = P(t.tx);
    const qq = U.pick(t.q);
    const tf = U.pick(t.tf);
    if (level === 1) return run([
      () => choice('О ком этот текст?', t.hero, U.pickN(t.hw, 2), { visual: vis, hint: 'Посмотри, кто действует в тексте', explain: 'Этот текст — про то, кто главный: ' + t.hero + '.' }),
      () => choice(qq[0], qq[1], U.pickN(qq[2], 2), { visual: vis, hint: 'Найди ответ в тексте', explain: U.cap(qq[1]) + '.' }),
      () => choice('Верно или неверно? <i>' + tf[0] + '</i>', tf[1] ? 'Верно' : 'Неверно', [tf[1] ? 'Неверно' : 'Верно'], { visual: vis, hint: 'Перечитай текст ещё раз', explain: tf[1] ? 'Это сказано в тексте — верно.' : 'В тексте такого нет — неверно.' }),
      () => choice('Какой заголовок подходит к тексту?', t.ti, U.pickN(t.tw, 2), { visual: vis, hint: 'Заголовок говорит о самом главном', explain: 'Лучший заголовок — ' + q(t.ti) + '.' })
    ]);
    if (level === 2) return run([
      () => choice(qq[0], qq[1], qq[2], { visual: vis, explain: U.cap(qq[1]) + '.' }),
      () => choice('Какой заголовок подходит к тексту?', t.ti, t.tw.slice(), { visual: vis, explain: 'Подходит заголовок ' + q(t.ti) + '.' }),
      () => choice('Верно или неверно? <i>' + tf[0] + '</i>', tf[1] ? 'Верно' : 'Неверно', [tf[1] ? 'Неверно' : 'Верно'], { visual: vis, explain: tf[1] ? 'В тексте так и написано.' : 'В тексте написано иначе.' }),
      () => order('Расставь события по порядку', t.ord.slice(), { visual: vis, explain: 'События идут так: ' + t.ord.join(' → ') + '.' }),
      () => input(t.n[0] + ' Напиши число', t.n[1], { visual: vis, explain: 'Ответ: ' + t.n[1] + '.' }),
      () => choice('О ком этот текст?', t.hero, t.hw.slice(), { visual: vis, explain: 'Главные герои текста — ' + t.hero + '.' })
    ]);
    return run([
      () => input(t.w[0], t.w[1].slice(), { visual: vis, hint: 'Слово есть в тексте', explain: 'Правильный ответ — ' + t.w[1][0] + '.' }),
      () => input(t.n[0] + ' Напиши число', t.n[1], { visual: vis, explain: 'В тексте сказано: ' + t.n[1] + '.' }),
      () => order('Расставь события по порядку', t.ord.slice(), { visual: vis, explain: 'Порядок: ' + t.ord.map((x, i) => (i + 1) + ') ' + x).join('; ') + '.' }),
      () => choice(qq[0], qq[1], qq[2].concat(U.pick(TXT.filter(x => x !== t)).q[0][2].slice(0, 1)), { visual: vis, explain: U.cap(qq[1]) + '.' }),
      () => choice('Какой заголовок подходит к тексту?', t.ti, t.tw.concat([U.pick(TXT.filter(x => x !== t)).ti]), { visual: vis, explain: 'Заголовок должен говорить о главном: ' + q(t.ti) + '.' }),
      () => multi('Выбери <b>все</b> верные утверждения', t.tf.filter(x => x[1]).map(x => x[0]), t.tf.filter(x => !x[1]).map(x => x[0]).concat(U.pickN(TXT.filter(x => x !== t), 2).map(x => x.tf.filter(y => !y[1])[0][0])), { visual: vis, explain: 'Верно то, что прямо сказано в тексте.' }),
      () => choice('Верно или неверно? <i>' + tf[0] + '</i>', tf[1] ? 'Верно' : 'Неверно', [tf[1] ? 'Неверно' : 'Верно'], { visual: vis, explain: tf[1] ? 'Верно: это есть в тексте.' : 'Неверно: в тексте сказано по-другому.' })
    ]);
  }

