  const RH_Q = [
    ['Что такое рифма?', 'созвучные концы строчек: кошка — окошко', ['начало строки', 'название стихотворения', 'знак в конце предложения']],
    ['Сколько строк в четверостишии?', 'четыре', ['две', 'три', 'пять']],
    ['Сколько строк в двустишии?', 'две', ['три', 'четыре', 'шесть']],
    ['Зачем в стихах нужна рифма?', 'чтобы стихи звучали складно и легко запоминались', ['чтобы было длиннее', 'чтобы спрятать смысл', 'чтобы не было картинок']],
    ['Чем стихи отличаются от рассказа?', 'строчки записаны в столбик и рифмуются', ['в стихах больше слов', 'стихи всегда о зверях', 'в стихах нет героев']],
    ['Как называют того, кто сочиняет стихи?', 'поэт', ['писатель', 'художник', 'читатель']],
    ['Какое слово рифмуется со словом «кошка»?', 'окошко', ['собака', 'котёнок', 'мышонок']],
    ['Какое слово рифмуется со словом «мороз»?', 'нос', ['зима', 'снег', 'холод']],
    ['Какое слово рифмуется со словом «лето»?', 'конфета', ['солнце', 'жара', 'каникулы']],
    ['Что нужно, чтобы слова рифмовались?', 'чтобы их концы звучали похоже', ['чтобы они начинались одинаково', 'чтобы они были одной длины', 'чтобы они были о природе']]
  ];
  const rhOther = (pair, n) => U.pickN(RHYMES.filter(x => x !== pair).map(x => x[1]), n);

  function genRhyme(level) {
    const r = U.pick(RHYMES);
    const c = U.pick(RH_COUPLETS);
    const rq = U.pick(RH_Q);
    if (level === 1) return run([
      () => choice('Найди рифму к слову <b>' + r[0] + '</b>', r[1], rhOther(r, 2), { hint: 'Слова должны заканчиваться похоже', explain: r[0] + ' — ' + r[1] + ': концы слов звучат одинаково.' }),
      () => gap('Договори стишок', c[0], [c[1]], c[2].slice(0, 1), { hint: 'Слово должно рифмоваться', explain: c[0].replace('_', c[1]) + '.' }),
      () => match('Соедини слова, которые рифмуются', RHYMES.map(x => [x[0], x[1]]), 3, { explain: 'Рифма — это созвучные концы слов.' }),
      () => { const a = U.pick(RH_Q.slice(0, 6)); return choice(a[0], a[1], U.pickN(a[2], 2), { hint: 'Вспомни, как устроено стихотворение', explain: U.cap(a[1]) + '.' }); },
      () => choice('Найди рифму к слову <b>' + r[1] + '</b>', r[0], U.pickN(RHYMES.filter(x => x !== r).map(x => x[0]), 2), { explain: r[1] + ' рифмуется со словом ' + r[0] + '.' })
    ]);
    if (level === 2) return run([
      () => choice('Найди рифму к слову <b>' + r[0] + '</b>', r[1], rhOther(r, 3), { explain: r[0] + ' — ' + r[1] + '.' }),
      () => gap('Договори стишок', c[0], [c[1]], c[2], { explain: c[0].replace('_', c[1]) + '.' }),
      () => match('Соедини слова, которые рифмуются', RHYMES.map(x => [x[0], x[1]]), 4, { explain: 'У рифмующихся слов одинаково звучат концы.' }),
      () => choice(rq[0], rq[1], rq[2], { explain: U.cap(rq[1]) + '.' }),
      () => { const ri = U.pick(RH_INPUT); const right = U.pickN(ri[1], 2); const wr = U.pickN(RHYMES.map(x => x[0]).filter(x => x !== ri[0] && !ri[1].includes(x)), 3); return multi('Выбери <b>все</b> слова, которые рифмуются со словом «' + ri[0] + '»', right, wr, { explain: 'Со словом «' + ri[0] + '» рифмуются: ' + ri[1].slice(0, 4).join(', ') + '.' }); },
      () => input('Сколько строк в четверостишии? Напиши число', 4, { explain: 'В четверостишии четыре строки — от слова «четыре».' })
    ]);
    return run([
      () => { const ri = U.pick(RH_INPUT); return input('Придумай рифму к слову <b>' + ri[0] + '</b> и напиши её', ri[1].slice(), { hint: 'Конец слова должен звучать так же', explain: 'Например: ' + ri[0] + ' — ' + ri[1][0] + '.' }); },
      () => input('Договори стишок одним словом: <b>' + c[0].replace('_', '…') + '</b>', [c[1]], { hint: 'Первая буква: ' + c[1][0], explain: c[0].replace('_', c[1]) + '.' }),
      () => match('Соедини слова, которые рифмуются', RHYMES.map(x => [x[0], x[1]]), 5, { explain: 'Печка — речка, мишка — шишка, кот — компот: рифма слышна в конце слова.' }),
      () => { const ri = U.pick(RH_INPUT); const right = U.pickN(ri[1], 3); const wr = U.pickN(RHYMES.map(x => x[0]).filter(x => x !== ri[0] && !ri[1].includes(x)), 3); return multi('Выбери <b>все</b> слова, которые рифмуются со словом «' + ri[0] + '»', right, wr, { explain: 'Рифма к слову «' + ri[0] + '»: ' + ri[1].slice(0, 5).join(', ') + '.' }); },
      () => choice(rq[0], rq[1], rq[2].concat(U.pick(RH_Q.filter(x => x !== rq))[2].slice(0, 1)), { explain: U.cap(rq[1]) + '.' }),
      () => choice('Найди рифму к слову <b>' + r[0] + '</b>', r[1], rhOther(r, 4), { explain: r[0] + ' — ' + r[1] + '.' }),
      () => gap('Договори стишок', c[0], [c[1]], c[2].concat([U.pick(RH_COUPLETS.filter(x => x !== c))[1]]), { explain: c[0].replace('_', c[1]) + '.' }),
      () => input('Сколько строк в двустишии? Напиши число', 2, { explain: 'Двустишие — это две строки, которые рифмуются.' })
    ]);
  }

